"""Draft topics for required Volume II, Chapters 7–8, and required Volume III, Chapter 9 (People's Education Press, 2019)."""
from phy_hs_lib import T, C, N

# ======================= Required Volume II, Chapter 7: Universal Gravitation and Spaceflight =======================
T("kepler", "Kepler's Laws", "Motion and Interaction",
  "Kepler's three laws state that planets move in elliptical orbits with the Sun at one focus; the line from a planet to the Sun sweeps out equal areas in equal times; and the ratio of the cube of an orbit's semi-major axis to the square of its orbital period is constant.",
  ["State Kepler's three laws", "Know that a planet moves faster at perihelion than at aphelion", "Use a³/T² = k to compare or calculate planetary orbits and periods"],
  [("B2.2.4", "exact")],
  pre=[("curve_motion", "soft"), ("circular", "soft")],
  math=[("cnm_h037", "a³ ∝ T² is a power-function relationship; T is proportional to a to the 3/2 power.")],
  qs=[
    C("basic", "Which statement about Kepler's first law is correct?", "All planets orbit the Sun in ellipses, with the Sun at one focus of each ellipse",
      ["All planets orbit the Sun in circles, with the Sun at the center", "All planets orbit the Sun in ellipses, with the Sun at the center of each ellipse", "All planets orbit the Sun in parabolas, with the Sun at the focus"],
      "Kepler's first law states that a planet's orbit is an ellipse with the Sun at one focus, not at the center; the orbit is not a perfect circle."),
    C("basic", "As a planet moves from perihelion to aphelion along an elliptical orbit, how does its speed change?", "It gradually decreases",
      ["It gradually increases", "It stays constant", "It first increases, then decreases"],
      "By Kepler's second law, the line from the planet to the Sun sweeps out equal areas in equal times. The planet is farther from the Sun at aphelion, so it moves more slowly to sweep out the same area; its speed therefore decreases from perihelion to aphelion."),
    N("standard", "A planet's orbital semi-major axis is 4 times Earth's. What is its orbital period in years? (Earth's orbital period is 1 year; enter a number only)", "8",
      "From a³/T² = k, T² = 4³ = 64 in Earth units, so T = 8 years. T = 4 years would be wrong because it treats period as proportional to orbital radius.", "sqrt(4**3)"),
    C("standard", "Which statement about Kepler's third law, a³/T² = k, is correct?", "k depends only on the central body and is the same for all planets orbiting the same central body",
      ["k depends on the planet's mass, and is larger for more massive planets", "The law applies only to elliptical orbits, not approximately circular ones", "Satellites orbiting Earth and planets orbiting the Sun have the same value of k"],
      "k is determined by the central body's mass, not the orbiting body's mass. The central bodies differ for planets orbiting the Sun and satellites orbiting Earth, so their k values differ. The law also applies to circular orbits, where a is the radius."),
  ])

T("gravitation", "Law of Universal Gravitation", "Motion and Interaction",
  "The law of universal gravitation states that any two objects attract each other, with a force proportional to the product of their masses and inversely proportional to the square of their separation: F = Gm₁m₂/r². Cavendish measured the gravitational constant G using a torsion balance.",
  ["Write the law of universal gravitation and explain its variables", "Compare gravitational forces at different distances using the inverse-square relationship", "Know that mutual gravitational forces form an action-reaction pair"],
  [("B2.2.4", "exact")],
  pre=[("kepler", "hard"), ("centripetal_force", "hard"), ("newton3", "soft")],
  math=[("cnm_h037", "Gravitational force is inversely proportional to the square of the distance, a power relationship used for comparisons.")],
  qs=[
    C("basic", "The distance between two point masses doubles, with all else unchanged. How does the gravitational force between them change?", "It becomes one quarter of the original",
      ["It becomes half the original", "It doubles", "It becomes four times the original"],
      "From F = Gm₁m₂/r², replacing r with 2r makes F one quarter as large. A common error is treating an inverse-square relationship as a simple inverse relationship and getting one half."),
    C("basic", "Which scientist first measured the gravitational constant G using a torsion balance?", "Cavendish",
      ["Kepler", "Galileo", "Tycho"],
      "Newton proposed the law of universal gravitation without giving a value for G. More than a century later, Cavendish measured G with a torsion balance and was called 'the man who weighed the Earth.'"),
    N("standard", "An object experiences a gravitational force of 400 N at Earth's surface. It is moved to an altitude equal to Earth's radius (a distance of 2R from Earth's center). What is the gravitational force there, in N? (Enter a number only)", "100",
      "Since F ∝ 1/r², changing r from R to 2R makes F one quarter as large: 400 ÷ 4 = 100 N. A simple inverse relationship would give 200 N. Here r is the distance from Earth's center, 2R, not the altitude R.", "400/(2**2)"),
    C("standard", "Which statement about the gravitational force between Earth and the Moon is correct?", "Earth's force on the Moon and the Moon's force on Earth are equal in magnitude and opposite in direction, forming an action-reaction pair",
      ["Earth's force on the Moon is greater because Earth has more mass", "The Moon's force on Earth is greater because the Moon needs centripetal force to orbit Earth", "The forces are equal in magnitude and form a balanced-force pair"],
      "The forces have equal magnitudes under F = Gm₁m₂/r². They act on different objects, so they form an action-reaction pair, not a balanced-force pair. Their masses affect their respective accelerations."),
  ])

T("celestial_calc", "Applications of Gravitation", "Motion and Interaction", "application",
  "Treating an astronomical body's orbit as circular motion powered by gravity lets us calculate the central body's mass from the orbiting body's radius and period, then find its density using its radius. Its mass can also be found from the surface gravitational acceleration, g = GM/R².",
  ["Find a central body's mass from GMm/r² = m·4π²r/T²", "Compare and calculate surface gravitational acceleration using g = GM/R²", "Find a central body's density from a near-surface orbit"],
  [("B2.2.4", "exact"), ("B2.2.5", "inferred")],
  pre=[("gravitation", "hard"), ("centripetal_force", "hard"), ("centripetal_accel", "soft"), ("J:density", "soft")],
  qs=[
    C("basic", "A satellite moves in a circular orbit around Earth. Given its orbital radius r and period T, which quantity can be found using only these values and the gravitational constant G?", "Earth's mass",
      ["The satellite's mass", "The magnitude of the gravitational force on the satellite", "The satellite's density"],
      "From GMm/r² = m·4π²r/T², the satellite's mass m cancels, giving M = 4π²r³/(GT²). This determines the central body's mass (Earth), not the orbiting body's mass or the force magnitude."),
    N("basic", "A planet is modeled as a uniform sphere with GM = 4×10¹⁴ m³/s² and radius R = 1×10⁷ m. Ignoring rotation, what is the gravitational acceleration at its surface, in m/s²? (Enter a number only)", "4",
      "Ignoring rotation, mg = GMm/R², so g = GM/R² = 4×10¹⁴ ÷ (1×10⁷)² = 4 m/s².", "4e14/(1e7)**2"),
    N("standard", "A planet has 8 times Earth's mass and twice Earth's radius. How many times Earth's surface gravitational acceleration is its surface gravitational acceleration? (Enter a number only)", "2",
      "Since g = GM/R², g_planet/g_Earth = 8 ÷ 2² = 2. Forgetting to square the radius gives 4; treating g as proportional to radius gives 16.", "8/2**2"),
    C("advanced", "A satellite moves in a near-surface circular orbit around a planet with period T. Given the gravitational constant G, what is the planet's mean density?", "3π/(GT²)",
      ["4π²/(GT²)", "3π/(GT)", "3π²/(GT²)"],
      "From GMm/R² = m·4π²R/T², M = 4π²R³/(GT²). With volume V = 4πR³/3, the density is ρ = M/V = 3π/(GT²); the radius R cancels."),
  ])

T("cosmic_speed", "Escape Velocities", "Motion and Interaction", "conceptual",
  "The first cosmic velocity, 7.9 km/s, is the orbital speed of a satellite near Earth's surface; it is both the maximum orbital speed and the minimum launch speed. The second cosmic velocity, 11.2 km/s, lets an object escape Earth. The third, 16.7 km/s, lets it leave the Solar System.",
  ["State the values and meanings of the three cosmic velocities", "Derive the first cosmic velocity using mg = mv²/R or GMm/R² = mv²/R", "Compare the first cosmic velocities of different celestial bodies"],
  [("B2.2.5", "exact")],
  pre=[("gravitation", "hard"), ("centripetal_accel", "hard"), ("celestial_calc", "soft")],
  qs=[
    C("basic", "What is the approximate value of the first cosmic velocity (orbital velocity)?", "7.9 km/s",
      ["11.2 km/s", "16.7 km/s", "9.8 km/s"],
      "The first cosmic velocity is about 7.9 km/s; 11.2 km/s is the second and 16.7 km/s is the third. The value 9.8 is gravitational acceleration in m/s², not a speed."),
    C("basic", "Which statement about the first cosmic velocity is correct?", "It is the maximum orbital speed of a satellite around Earth and the minimum launch speed",
      ["It is the minimum orbital speed of a satellite around Earth", "It is the maximum launch speed for a satellite; above it, the satellite falls back to Earth", "It is the minimum launch speed needed to escape Earth's gravitational pull"],
      "From v = √(GM/r), orbital speed decreases as the orbit gets higher; 7.9 km/s is the maximum, near Earth's surface. Reaching a higher orbit requires a greater launch speed, so 7.9 km/s is the minimum launch speed. Escaping Earth requires 11.2 km/s."),
    N("standard", "Earth's radius is R = 6.4×10⁶ m and the gravitational acceleration near its surface is g = 10 m/s². What is the orbital speed of a near-Earth satellite, in m/s? (Enter a number only)", "8000",
      "Gravity provides the centripetal force for a near-Earth satellite: mg = mv²/R, so v = √(gR) = √(10 × 6.4×10⁶) = 8000 m/s.", "sqrt(10*6.4e6)"),
    N("advanced", "Take Earth's first cosmic velocity as 8 km/s. Another planet has one eighth of Earth's mass and half its radius. What is its first cosmic velocity, in km/s? (Enter a number only)", "4",
      "Since v = √(GM/R), v_planet/v_Earth = √[(1/8)/(1/2)] = √(1/4) = 1/2, so v_planet = 4 km/s.", "8*sqrt((1/8)/(1/2))"),
  ])

T("satellite_orbit", "Artificial Satellite Orbits", "Motion and Interaction", "reasoning",
  "For a satellite in a circular orbit around Earth, gravity provides the centripetal force. Linear speed, angular speed, period, and centripetal acceleration all depend on the orbital radius: a higher orbit has lower v, ω, and a but a longer T. A geostationary satellite has a fixed orbit and period.",
  ["Derive how each quantity depends on r from GMm/r² = mv²/r = mω²r = m4π²r/T² = ma", "Compare v, ω, T, and a for satellites in different orbits", "Know the properties of geostationary satellites"],
  [("B2.2.5", "exact"), ("B2.2.3", "inferred")],
  pre=[("celestial_calc", "hard"), ("cosmic_speed", "hard"), ("circular", "hard")],
  math=[("cnm_h037", "Relationships such as v ∝ r^(-1/2) and T ∝ r^(3/2) are power functions.")],
  qs=[
    C("basic", "A satellite moves in a circular orbit around Earth. What happens to its orbital quantities when the radius increases?", "Linear speed, angular speed, and centripetal acceleration decrease; the period increases",
      ["Linear speed increases, angular speed decreases, and the period increases", "Linear speed, angular speed, centripetal acceleration, and period all decrease", "Linear speed and period increase, while centripetal acceleration decreases"],
      "From GMm/r² = mv²/r = mω²r = m4π²r/T² = ma, we get v = √(GM/r), ω = √(GM/r³), T = 2π√(r³/GM), and a = GM/r². As r increases, v, ω, and a decrease while T increases. Do not infer that a larger r means a larger v just from v = ωr."),
    N("basic", "Earth's surface gravitational acceleration is g = 10 m/s²; ignore rotation. A satellite orbits Earth with a radius (measured from Earth's center) of 2R, where R is Earth's radius. What is its centripetal acceleration, in m/s²? (Enter a number only)", "2.5",
      "Since a = GM/r² and r = 2R, a = g/4 = 2.5 m/s². Treating 2R as the altitude above the surface (making the distance from Earth's center 3R) would give 10/9 m/s².", "10/2**2"),
    N("standard", "Satellites A and B orbit the same planet. B's orbital radius is 4 times A's, and A's period is 3 h. What is B's period in hours? (Enter a number only)", "24",
      "From T = 2π√(r³/GM), T is proportional to r^(3/2): T_B = 3 × 4^(3/2) = 3 × 8 = 24 h. Treating T as proportional to r would give 12 h.", "3*4**1.5"),
    C("standard", "Which statement about geostationary satellites is correct?", "Their orbital planes coincide with Earth's equatorial plane, and their speed is less than the first cosmic velocity",
      ["Any satellite with a 24 h period can remain fixed directly above Beijing", "Because their orbit is higher than a near-Earth orbit, their speed exceeds the first cosmic velocity", "A more massive geostationary satellite has a larger orbital radius"],
      "A geostationary satellite has the same period as Earth's rotation and appears stationary relative to the ground. It must orbit above the equator, and its orbital radius is fixed regardless of mass. From v = √(GM/r), its higher orbit means its speed is below 7.9 km/s."),
  ])

T("relativity", "Relativity and the Limits of Newtonian Mechanics", "Matter", "conceptual",
  "The two postulates of special relativity are the principle of relativity and the invariance of the speed of light. They lead to time dilation and length contraction. Newtonian mechanics applies to macroscopic objects moving at low speeds, not to microscopic or near-light-speed motion.",
  ["State the invariance-of-light-speed principle and the scope of Newtonian mechanics", "Describe time dilation and length contraction qualitatively", "Use l = l₀√(1 − v²/c²) in simple calculations"],
  [("B2.3.1", "exact"), ("B2.3.2", "exact")],
  pre=[("newton2", "soft"), ("velocity", "soft")],
  qs=[
    C("basic", "What does the invariance-of-light-speed principle in special relativity state?", "The speed of light in a vacuum has the same value in every inertial reference frame",
      ["The speed of light is the source's speed plus the speed of the light itself", "The speed of light in a vacuum increases with the source's speed", "Light is measured to be slower in a moving frame than in a stationary frame"],
      "The principle states that the speed of light in a vacuum is the same in all inertial reference frames, independent of the motion of the source or observer. This differs from classical velocity addition."),
    C("basic", "What is the scope of Newtonian mechanics?", "Low-speed motion of macroscopic objects (at speeds far below the speed of light)",
      ["Low-speed motion of microscopic particles", "Motion of macroscopic objects near the speed of light", "High-speed motion of microscopic particles"],
      "Newtonian mechanics applies to macroscopic, low-speed motion. Relativity is needed near the speed of light, and quantum mechanics is needed for microscopic particles."),
    C("standard", "A spacecraft travels at a speed close to that of light relative to Earth. What does an observer on Earth see when comparing a clock on the spacecraft with an identical clock on Earth?", "The spacecraft's clock runs more slowly",
      ["The spacecraft's clock runs faster", "The spacecraft's clock runs at the same rate", "The spacecraft's clock stops completely because of its speed"],
      "Time dilation means that a clock moving relative to an observer runs more slowly. The effect becomes more pronounced as the object's speed approaches the speed of light."),
    N("advanced", "A rod has a rest length of 10 m and moves parallel to its length at 0.6c relative to Earth. What length does an observer on Earth measure, in meters? (Enter a number only)", "8",
      "Length contraction gives l = l₀√(1 − v²/c²) = 10 × √(1 − 0.36) = 10 × 0.8 = 8 m. Length contracts along the direction of motion; it does not increase.", "10*sqrt(1-0.6**2)"),
  ])

# ======================= Required Volume II, Chapter 8: Conservation of Mechanical Energy =======================
T("work", "Work", "Energy", "procedural",
  "Work depends on the force and the displacement in the force's direction: W = Fl cosα, where α is the angle between force and displacement. Work is a scalar: it is positive for 0° ≤ α < 90°, zero for α = 90°, and negative for 90° < α ≤ 180° (work done against the force). Net work is the algebraic sum of the work done by all forces.",
  ["Calculate work by a constant force using W = Fl cosα", "Understand that work is a scalar and identify positive, negative, and zero work", "Find net work or the algebraic sum of the work done by each force"],
  [("B2.1.1", "exact")],
  pre=[("J:work", "hard"), ("force_decompose", "hard"), ("displacement", "soft")],
  math=[("cnm_h060", "W = Fl cosα uses the definition and values of the trigonometric cosine function.")],
  qs=[
    N("basic", "A 10 N force pulls a box 4 m along a level floor at 60° above the horizontal. How much work does the force do, in joules? (cos60° = 0.5; enter a number only)", "20",
      "W = Fl cosα = 10 × 4 × 0.5 = 20 J. Using sin60° would give about 34.6 J; omitting cosα would give 40 J.", "10*4*0.5"),
    C("basic", "Which statement about work is correct?", "Work is a scalar; positive work means the force drives the motion, while negative work means it resists the motion",
      ["Work is a vector, and its sign shows its direction", "A larger force and displacement always mean more work", "If a force does negative work, it has done no work on the object"],
      "Work is a scalar; its sign indicates whether a force drives or resists motion. From W = Fl cosα, a perpendicular force does no work because cosα = 0, regardless of displacement. Negative work means the object works against the force."),
    N("standard", "A 2 kg object slides 5 m from rest down a smooth incline at 30°. How much work does gravity do, in joules? (g = 10 m/s², sin30° = 0.5; enter a number only)", "50",
      "Work by gravity depends only on the height change: h = 5 × sin30° = 2.5 m, so W = mgh = 2 × 10 × 2.5 = 50 J. Using mg × 5 directly gives 100 J because it ignores the angle between gravity and the displacement.", "2*10*5*0.5"),
    N("advanced", "A 10 kg box rests on a level floor. A 50 N force pulls it 2 m at 37° above the horizontal. The coefficient of kinetic friction is 0.5. What is the total work done by all forces on the box, in joules? (g = 10 m/s², sin37° = 0.6, cos37° = 0.8; enter a number only)", "10",
      "The normal force is N = mg − F sin37° = 100 − 30 = 70 N, so friction is f = μN = 35 N. The pulling force does W_pull = 50 × 0.8 × 2 = 80 J, and friction does W_friction = −35 × 2 = −70 J. Gravity and the normal force do no work, so the total is 80 − 70 = 10 J. Using N = mg would give −20 J.", "50*0.8*2-0.5*(10*10-50*0.6)*2"),
  ])

T("power", "Power", "Energy", "procedural",
  "Power measures the rate of doing work. P = W/t gives average power over a time interval t. In P = Fv cosα, v is instantaneous velocity for instantaneous power and average velocity for average power. A vehicle running at rated power has F = P/v.",
  ["Distinguish average power from instantaneous power", "Calculate power using P = W/t and P = Fv", "Analyze the maximum speed of a vehicle moving at rated power"],
  [("B2.1.1", "exact")],
  pre=[("work", "hard"), ("velocity", "hard"), ("J:power", "soft")],
  qs=[
    C("basic", "What kind of power is calculated by P = W/t? (t is the time taken to do the work)", "Average power over that time interval",
      ["Instantaneous power at a particular moment", "The machine's rated power", "The maximum power during that interval"],
      "W/t is work divided by the time taken. It gives the average rate of doing work over the interval. Use P = Fv for instantaneous power, with v as instantaneous velocity."),
    N("basic", "A crane raises a 500 kg load 10 m at constant speed in 20 s. What is the crane's average power, in watts? (g = 10 m/s²; enter a number only)", "2500",
      "At constant speed, F = mg = 5000 N. Then W = Fh = 5000 × 10 = 5×10⁴ J, and P = W/t = 50000 ÷ 20 = 2500 W.", "500*10*10/20"),
    N("standard", "A car has a rated power of 60 kW and experiences a constant 2000 N drag force on a level road. What is its maximum speed, in m/s? (Enter a number only)", "30",
      "At maximum speed the acceleration is zero, so the driving force F equals the drag f. From P = Fv, v = P/f = 60000 ÷ 2000 = 30 m/s. Convert kW to W.", "60000/2000"),
    C("standard", "A 2 kg object falls freely from rest with no air resistance (g = 10 m/s²). What is the instantaneous power of gravity at the end of 3 s?", "600 W",
      ["300 W", "900 W", "1800 W"],
      "At the end of 3 s, v = gt = 30 m/s and P = mgv = 20 × 30 = 600 W. 300 W is the average power over the first 3 s (average speed 15 m/s); 900 W results from treating the 45 m fall distance as a speed, and 1800 W from multiplying by t again.", verify="2*10*10*3"),
  ])

T("gravity_pe", "Gravitational Potential Energy", "Energy", "conceptual",
  "Gravitational potential energy is energy an object has because of its height: Ep = mgh, where h is measured relative to a reference plane. Its value depends on the chosen plane. Work by gravity is path-independent: W_G = Ep1 − Ep2. Positive work by gravity decreases potential energy.",
  ["Calculate gravitational potential energy using Ep = mgh and explain the role of the reference plane", "Know that work by gravity is path-independent", "Infer changes in gravitational potential energy from work by gravity"],
  [("B2.1.3", "exact")],
  pre=[("work", "hard"), ("gravity", "hard"), ("J:kinetic", "soft")],
  qs=[
    N("basic", "A 2 kg object is 5 m above the ground. Taking the ground as the reference plane, what is its gravitational potential energy in joules? (g = 10 m/s²; enter a number only)", "100",
      "Ep = mgh = 2 × 10 × 5 = 100 J.", "2*10*5"),
    C("basic", "An object falls from a height under gravity. Which statement about work by gravity and gravitational potential energy is correct?", "Gravity does positive work, and gravitational potential energy decreases by the amount of work done",
      ["Gravity does positive work, and gravitational potential energy increases by the amount of work done", "Gravity does positive work, and gravitational potential energy decreases by an amount that depends on the path", "Gravity does positive work, and gravitational potential energy stays constant"],
      "Work by gravity is W_G = Ep1 − Ep2 and depends only on the height difference between the initial and final positions, not the path. Positive work means potential energy decreases by the amount of work done."),
    N("standard", "A desk is 0.8 m above the ground. A 1 kg ball is 0.5 m above the desk. Taking the ground as the reference plane, what is the ball's gravitational potential energy in joules? (g = 10 m/s²; enter a number only)", "13",
      "The ball is h = 0.8 + 0.5 = 1.3 m above the ground, so Ep = mgh = 1 × 10 × 1.3 = 13 J. Relative to the desk, it would be 5 J; the value depends on the reference plane.", "1*10*(0.8+0.5)"),
    C("standard", "If the reference plane for gravitational potential energy changes, which quantity changes?", "The numerical value of an object's gravitational potential energy at a position",
      ["The change in gravitational potential energy as the object moves from A to B", "The work done by gravity as the object moves from A to B", "The difference in gravitational potential energy between A and B"],
      "The value of gravitational potential energy is relative to the reference plane. Its change is the negative of the work done by gravity and depends only on the height difference, not on the reference plane."),
  ])

T("elastic_pe", "Elastic Potential Energy", "Energy", "conceptual",
  "Elastic potential energy is energy stored when parts of an elastically deformed object interact through elastic forces. A spring's elastic potential energy depends on its deformation and spring constant; greater deformation means more energy. Positive work by the elastic force decreases this energy, while work against the force increases it.",
  ["Know that elastic potential energy depends on deformation", "Infer changes in elastic potential energy from work by the elastic force", "Find work against an elastic force from the area under an F-x graph"],
  [("B2.1.3", "exact")],
  pre=[("work", "hard"), ("elastic_force", "hard"), ("gravity_pe", "soft")],
  qs=[
    C("basic", "A light spring has an unstretched length of 10 cm. It is stretched to 12 cm or compressed to 8 cm, both within its elastic limit. How do the spring's elastic potential energies compare?", "They are equal",
      ["The stretched spring has more", "The compressed spring has more", "One is positive and the other is negative"],
      "Elastic potential energy depends on the magnitude of the deformation. Both cases have a deformation of 2 cm, so their energies are equal and neither is negative."),
    C("basic", "A spring gradually returns from a compressed state to its natural length. Which statement is correct?", "The elastic force does positive work, and elastic potential energy decreases",
      ["The elastic force does positive work, and elastic potential energy increases", "The elastic force does negative work, and elastic potential energy decreases", "The elastic force does negative work, and elastic potential energy increases"],
      "As the spring returns to its natural length, the elastic force and displacement point in the same direction. The force does positive work, deformation decreases, and elastic potential energy decreases by the amount of work done."),
    N("standard", "A spring is stretched slowly as the pulling force increases uniformly from 0 to 20 N. The spring extends by 0.1 m. By how many joules does its elastic potential energy increase? (Enter a number only)", "1",
      "The pulling force varies, so the area under the F-x graph gives the work: W = ½ × 20 × 0.1 = 1 J. For a slow stretch, work against the elastic force equals the increase in elastic potential energy. Using 20 × 0.1 = 2 J incorrectly treats the force as constant.", "0.5*20*0.1"),
    C("standard", "A spring's elastic potential energy is proportional to the square of its deformation. Within the elastic limit, what happens to the energy if the deformation doubles?", "It becomes four times as large",
      ["It doubles", "It becomes eight times as large", "It becomes sixteen times as large"],
      "Ep ∝ x², so doubling x multiplies Ep by 2² = 4. Do not treat potential energy as proportional to deformation.", verify="2**2"),
  ])

T("kinetic_energy", "Kinetic Energy", "Energy", "conceptual",
  "Kinetic energy is the energy an object has because of its motion: Ek = ½mv². It is a nonnegative scalar, independent of the direction of velocity. A change in velocity does not always change kinetic energy, as in uniform circular motion. Kinetic energy is proportional to the square of speed.",
  ["Calculate and compare kinetic energies using Ek = ½mv²", "Know that kinetic energy is a scalar independent of velocity direction", "Convert speed units and calculate changes in kinetic energy"],
  [("B2.1.2", "exact")],
  pre=[("work", "hard"), ("J:kinetic", "soft")],
  math=[("cnm_h037", "Kinetic energy is proportional to the square of speed, so doubling speed makes it four times larger.")],
  qs=[
    N("basic", "A 2 kg object moves at 3 m/s. What is its kinetic energy in joules? (Enter a number only)", "9",
      "Ek = ½mv² = 0.5 × 2 × 3² = 9 J. Omitting ½ gives 18 J; omitting the square gives 3 J.", "0.5*2*3**2"),
    C("basic", "Which statement about kinetic energy is correct?", "Kinetic energy is a scalar whose value is independent of the direction of velocity",
      ["Kinetic energy can be negative, indicating motion in the negative direction", "Whenever an object's velocity changes, its kinetic energy changes", "For equal masses, the faster object has less kinetic energy"],
      "Kinetic energy, ½mv², is a nonnegative scalar. It remains unchanged if direction changes while speed stays constant, as in uniform circular motion. For equal masses, greater speed means greater kinetic energy."),
    N("standard", "A 1000 kg car speeds up from 36 km/h to 72 km/h. By how many joules does its kinetic energy increase? (Enter a number only)", "150000",
      "First convert speeds: 36 km/h = 10 m/s and 72 km/h = 20 m/s. ΔEk = ½m(v₂² − v₁²) = 0.5 × 1000 × (400 − 100) = 150000 J. Using only the speed difference of 10 m/s gives 50000 J.", "0.5*1000*(20**2-10**2)"),
    C("standard", "Objects A and B have a mass ratio of 1:2 and a speed ratio of 2:1. What is the ratio of their kinetic energies?", "2:1",
      ["1:1", "4:1", "1:2"],
      "Ek = ½mv², so Ek_A : Ek_B = (1 × 2²) : (2 × 1²) = 4 : 2 = 2 : 1. The ratio 1:1 treats the momentum ratio mv as the kinetic-energy ratio; 4:1 ignores the mass difference."),
  ])

T("work_energy_theorem", "Work–Energy Theorem", "Energy", "reasoning",
  "The work–energy theorem states that the total work done by the net force equals the change in kinetic energy: W_net = Ek2 − Ek1. It applies to constant or variable forces and to straight or curved motion; only the initial and final states and the work done by each force are needed.",
  ["State the work–energy theorem and explain total work", "Use the theorem to find speed, displacement, or a force", "Solve a single-process problem involving variable-force work"],
  [("B2.1.2", "exact")],
  pre=[("kinetic_energy", "hard"), ("work", "hard"), ("newton2", "soft"), ("vx_formula", "soft")],
  qs=[
    N("basic", "A 2 kg object speeds up from 2 m/s to 6 m/s under a net force. How much work does the net force do, in joules? (Enter a number only)", "32",
      "By the work–energy theorem, W_net = ½mv₂² − ½mv₁² = 0.5 × 2 × (36 − 4) = 32 J.", "0.5*2*(6**2-2**2)"),
    C("basic", "Which statement about the work–energy theorem is correct?", "The total work done by the net force equals the change in the object's kinetic energy",
      ["The work done by the net force equals the object's final kinetic energy", "The work done by any one force equals the change in kinetic energy", "The work done by the net force equals the change in velocity"],
      "The theorem is W_net = Ek2 − Ek1: total work, the algebraic sum of the work done by all forces, equals the change in kinetic energy. It is not the final kinetic energy or the work done by just one force."),
    N("standard", "A 1000 kg car travels at 20 m/s, then coasts 40 m on a level road and stops. What is the magnitude of the constant resistive force, in newtons? (Enter a number only)", "5000",
      "The work–energy theorem gives −f·s = 0 − ½mv², so f = ½mv²/s = 0.5 × 1000 × 400 ÷ 40 = 5000 N.", "0.5*1000*20**2/40"),
    N("advanced", "A 0.5 kg ball falls from rest from a height of 20 m and reaches the ground at 16 m/s. How much work is done against air resistance, in joules? (g = 10 m/s²; enter a number only)", "36",
      "The work–energy theorem gives mgh + W_drag = ½mv², so 100 + W_drag = 0.5 × 0.5 × 256 = 64 and W_drag = −36 J. Thus, 36 J of work is done against drag. Ignoring drag would give an impact speed of 20 m/s, inconsistent with the given value.", "0.5*10*20-0.5*0.5*16**2"),
  ])

T("energy_conservation", "Law of Conservation of Mechanical Energy", "Energy", "reasoning",
  "In a system where only gravity or internal elastic forces do work, kinetic and potential energy can convert into each other while total mechanical energy remains constant. Check which forces do work, then apply Ek1 + Ep1 = Ek2 + Ep2.",
  ["Determine whether mechanical energy is conserved in a process", "Use conservation of mechanical energy to find speed or height", "Combine energy conservation with circular motion to find a force"],
  [("B2.1.4", "exact")],
  pre=[("gravity_pe", "hard"), ("elastic_pe", "hard"), ("work_energy_theorem", "hard"), ("J:mech_energy", "soft"), ("centripetal_force", "soft")],
  qs=[
    C("basic", "What is the condition for conservation of mechanical energy?", "Only gravity or internal elastic forces do work",
      ["The net external force on the object is zero", "The object moves at constant velocity in a straight line", "The object experiences no friction"],
      "Mechanical energy is conserved when only gravity or internal elastic forces do work. Zero net force or constant-velocity motion keeps kinetic energy constant, but a change in height can still change mechanical energy. With no friction, an applied pull can still do work and change mechanical energy."),
    N("basic", "A ball is released from rest from a height of 5 m. Ignoring air resistance, what is its speed on reaching the ground, in m/s? (g = 10 m/s²; enter a number only)", "10",
      "Conservation of mechanical energy gives mgh = ½mv², so v = √(2gh) = √(2 × 10 × 5) = 10 m/s.", "sqrt(2*10*5)"),
    C("standard", "A ball of mass m falls freely, contacts a light vertical spring on the ground, and compresses it to its maximum. Ignoring air resistance, which statement is correct from spring contact to maximum compression?", "The ball-spring system conserves mechanical energy, while the ball's mechanical energy decreases",
      ["The ball's mechanical energy is conserved because only gravity and elastic forces do work", "The ball-spring system does not conserve mechanical energy because the spring does negative work on the ball", "The ball's mechanical energy increases while the spring's elastic potential energy decreases"],
      "Only gravity and elastic forces do work within the system, so its mechanical energy is conserved. The spring does negative work on the ball, reducing the ball's mechanical energy and transferring it to the spring. The ball alone does not conserve mechanical energy."),
    N("advanced", "A 1 kg ball starts from rest at the top of a smooth quarter-circle track of radius R = 0.8 m. What normal force does the track exert on the ball at the lowest point, in newtons? (g = 10 m/s²; enter a number only)", "30",
      "Energy conservation gives mgR = ½mv², so v² = 2gR = 16. At the lowest point, N − mg = mv²/R, so N = 10 + 16 ÷ 0.8 = 30 N. By Newton's third law, the ball exerts a 30 N force on the track (3mg).", "1*10+1*(2*10*0.8)/0.8"),
  ])

T("exp_energy", "Experiment: Verifying Conservation of Mechanical Energy", "Energy", "procedural",
  "Let a weight fall freely and use a ticker-tape record to measure its fall height h and corresponding instantaneous speed v. Compare mgh with ½mv² (or gh with v²/2) to test conservation of mechanical energy. Find instantaneous speed using the average speed over an interval centered on the point; do not use v = gt or v = √(2gh).",
  ["Identify the apparatus, procedure, and precautions", "Use a ticker tape and average speed to find instantaneous speed at a point", "Calculate the decrease in gravitational potential energy and increase in kinetic energy, and analyze errors"],
  [("B2.X.1", "exact"), ("B2.1.4", "inferred")],
  pre=[("energy_conservation", "hard"), ("exp_vt", "hard"), ("free_fall", "soft")],
  qs=[
    C("basic", "In the experiment to verify conservation of mechanical energy, which statement is correct?", "It is sufficient to check whether gh equals v²/2; the falling object's mass need not be measured",
      ["The falling object's mass must be measured with a balance", "A stopwatch must be used to measure the fall time", "Release the tape before switching on the ticker timer"],
      "The mass m cancels from mgh = ½mv², so it need not be measured. Time intervals come from the ticker-timer marks, so no stopwatch is needed. Turn on the timer and let it stabilize before releasing the tape."),
    C("basic", "Which falling object should be chosen to reduce experimental error?", "A heavy, compact object (such as a metal hammer)",
      ["A light, large object", "A heavy, large object", "A light, compact object"],
      "A heavy, compact object experiences relatively little air resistance compared with its weight. Friction on the tape is also relatively small, reducing mechanical-energy loss and error."),
    N("standard", "A ticker timer makes marks every 0.02 s. On a tape, the distance between three consecutive marks A, B, and C is AC = 7.2 cm. What is the object's instantaneous speed at B, in m/s? (Enter a number only)", "1.8",
      "B is the midpoint in time between A and C, so v_B = x_AC/(2T) = 0.072 ÷ 0.04 = 1.8 m/s. Convert centimeters to meters; the time interval is two periods.", "round(0.072/(2*0.02),2)"),
    N("advanced", "In an experiment, a 1 kg weight falls 0.5 m from O to P. Its measured speed at P is 3.0 m/s (g = 9.8 m/s²). By how many joules does the decrease in gravitational potential energy exceed the increase in kinetic energy? (Enter a number only)", "0.4",
      "ΔEp = mgh = 1 × 9.8 × 0.5 = 4.9 J, while ΔEk = ½mv² = 0.5 × 1 × 9 = 4.5 J, a difference of 0.4 J. ΔEp is slightly greater than ΔEk because friction between the tape and guide and air resistance do negative work.", "round(1*9.8*0.5-0.5*1*3.0**2,2)"),
  ])

# ======================= Required Volume III, Chapter 9: Electrostatic Fields and Their Applications =======================
T("charge", "Electric Charge", "Motion and Interaction", "conceptual",
  "There are two kinds of electric charge, positive and negative; like charges repel and unlike charges attract. Charging by friction, contact, and induction all involve electron transfer. Charge is conserved: it is neither created nor destroyed. The elementary charge is e = 1.6×10⁻¹⁹ C.",
  ["Explain that all three charging methods involve electron transfer", "Use charge conservation and equal sharing to find charge after contact", "Know the elementary charge and calculate the number of electrons gained or lost"],
  [("B3.1.1", "exact")],
  pre=[("J:charge", "hard"), ("J:molecule", "soft")],
  qs=[
    C("basic", "What is the physical mechanism behind charging by friction?", "Electrons transfer from one object to another",
      ["Friction creates new charge", "Protons transfer from one object to another", "Positive charges transfer from one object to another"],
      "Protons are tightly bound in atomic nuclei and cannot move freely. Charging by friction transfers electrons: an object that loses electrons becomes positive, while one that gains electrons becomes negative. Charge is not created."),
    C("basic", "Two identical small metal spheres carry charges of +6×10⁻⁸ C and −2×10⁻⁸ C. They touch and are then separated. What is the charge on each sphere?", "+2×10⁻⁸ C",
      ["+4×10⁻⁸ C", "+3×10⁻⁸ C", "−2×10⁻⁸ C"],
      "Charge is conserved: the total is 6 − 2 = +4 (×10⁻⁸ C). Identical spheres share it equally after contact, so each carries +2×10⁻⁸ C. +4 forgets to divide by two; +3 ignores the negative charge; −2 copies the original charge of the negatively charged sphere."),
    C("standard", "A positively charged sphere C is brought near, but does not touch, two initially neutral metal spheres A and B that are touching, with A nearer C. A and B are separated before C is removed. What are their charges?", "A is negative and B is positive",
      ["A is positive and B is negative", "Both A and B are positive", "Both A and B are neutral"],
      "By electrostatic induction, the positive charge on C attracts free electrons toward the nearer end, A, making A negative. B loses electrons and becomes positive. Separating A and B before removing C preserves their respective charges."),
    N("standard", "An object has a negative charge of 4.8×10⁻¹⁷ C. How many more electrons does it have than when neutral? (Elementary charge e = 1.6×10⁻¹⁹ C; enter a number only)", "300",
      "n = Q/e = 4.8×10⁻¹⁷ ÷ 1.6×10⁻¹⁹ = 300 electrons. A negative charge means the object has gained electrons; their number is the charge magnitude divided by the elementary charge.", "round(4.8e-17/1.6e-19)"),
  ])

T("coulomb", "Coulomb's Law", "Motion and Interaction", "procedural",
  "Coulomb's law states that the force between two stationary point charges in a vacuum is proportional to the product of their charges and inversely proportional to the square of their separation. It acts along the line joining them: F = kq₁q₂/r², where k = 9.0×10⁹ N·m²/C². Like charges repel; unlike charges attract.",
  ["Calculate the magnitude of the Coulomb force using F = kq₁q₂/r²", "Determine its direction and compare how it changes", "Analyze the equilibrium of point charges"],
  [("B3.1.2", "exact")],
  pre=[("charge", "hard"), ("force_compose", "soft"), ("newton3", "soft"), ("equilibrium", "soft")],
  math=[("cnm_h037", "Coulomb force is inversely proportional to the square of distance, a power-law inverse-square relationship.")],
  qs=[
    N("basic", "Two stationary point charges in a vacuum each have charge 2×10⁻⁶ C and are 0.2 m apart. What is the magnitude of the Coulomb force between them, in newtons? (k = 9×10⁹ N·m²/C²; enter a number only)", "0.9",
      "F = kq₁q₂/r² = 9×10⁹ × 2×10⁻⁶ × 2×10⁻⁶ ÷ 0.2² = 0.036 ÷ 0.04 = 0.9 N.", "round(9e9*2e-6*2e-6/0.2**2,2)"),
    C("basic", "In a vacuum, the distance between two point charges doubles, one charge doubles, and the other stays constant. How does the Coulomb force change?", "It becomes half the original",
      ["It becomes one quarter of the original", "It doubles", "It becomes one eighth of the original"],
      "Since F ∝ q₁q₂/r², the charge product doubles while r² quadruples, so F changes by a factor of 2/4 = 1/2."),
    C("standard", "Two point charges A and B in a vacuum have charges such that A's charge is four times B's. Which statement about the force between them is correct?", "The force of A on B and the force of B on A have equal magnitudes",
      ["The force of A on B is four times the force of B on A", "The force of B on A is four times the force of A on B", "The force of A on B is twice the force of B on A"],
      "The Coulomb forces between two charges form an action-reaction pair. From F = kq₁q₂/r², their magnitudes are always equal, regardless of the relative charge magnitudes."),
    N("advanced", "Two like point charges, A (+4Q) and B (+Q), are fixed 0.3 m apart in a vacuum. A third point charge C is placed on the line AB so that the net force on it is zero. How far from B should C be placed, in meters? (Enter a number only)", "0.1",
      "C must lie between A and B to balance the forces. Let its distance from B be x: k·4Q·q/(0.3 − x)² = k·Q·q/x², giving 2x = 0.3 − x and x = 0.1 m. This position does not depend on C's charge or its sign.", "0.3/3"),
  ])

T("e_field", "Electric Field Strength", "Motion and Interaction", "conceptual",
  "An electric field is a physical field surrounding electric charges. Electric-field strength E = F/q is a ratio definition describing field strength; it is determined by the field itself, not by the test charge. Its direction is defined as the force direction on a positive charge. The field of a point charge in a vacuum is E = kQ/r².",
  ["Understand E = F/q as a ratio definition independent of F and q", "Determine field direction using the force direction on a positive charge", "Calculate the field of a point charge using E = kQ/r²"],
  [("B3.1.3", "exact")],
  pre=[("coulomb", "hard"), ("newton2", "soft")],
  qs=[
    N("basic", "A 2×10⁻⁹ C test charge placed at a point in an electric field experiences a force of 6×10⁻⁶ N. What is the field strength there, in N/C? (Enter a number only)", "3000",
      "E = F/q = 6×10⁻⁶ ÷ 2×10⁻⁹ = 3000 N/C.", "round(6e-6/2e-9)"),
    C("basic", "The direction of the electric-field strength at a point is the same as which direction?", "The force on a positive charge at that point",
      ["The force on a negative charge at that point", "The direction in which a test charge moves", "The force on a test charge, regardless of its sign"],
      "The field direction is defined as the force direction on a positive charge. A negative charge experiences force in the opposite direction; a charge's motion need not be along its force."),
    N("standard", "A point charge Q = 4×10⁻⁹ C creates an electric field in a vacuum. What is the field strength 0.3 m away, in N/C? (k = 9×10⁹ N·m²/C²; enter a number only)", "400",
      "E = kQ/r² = 9×10⁹ × 4×10⁻⁹ ÷ 0.3² = 36 ÷ 0.09 = 400 N/C. Using r instead of r² would give 120 N/C.", "round(9e9*4e-9/0.3**2)"),
    C("standard", "A test charge q at a point experiences force F in an electric field of strength E. If it is replaced by a charge of 2q, what happens at that point?", "The field strength remains E, and the electric force becomes 2F",
      ["The field strength becomes 2E, and the force becomes 2F", "The field strength becomes E/2, and the force stays F", "Neither the field strength nor the force changes"],
      "Field strength is determined by the field, not the test charge, so it remains E. Since F = qE, doubling the charge doubles the force."),
  ])

T("field_lines", "Electric Field Lines and Superposition", "Motion and Interaction", "reasoning",
  "Electric field lines are imaginary curves used to represent a field. The tangent gives the field direction, and line density indicates field strength. They start at positive charges (or infinity), end at negative charges (or infinity), and never cross. Fields from multiple charges combine by vector addition using the parallelogram rule.",
  ["State the properties of field lines and determine field strength and direction", "Combine electric fields using the parallelogram rule", "Determine the force and motion directions of a charge in an electric field"],
  [("B3.1.3", "exact")],
  pre=[("e_field", "hard"), ("force_compose", "hard")],
  math=[("cnm_h081", "Electric-field superposition is vector addition using the parallelogram rule.")],
  qs=[
    C("basic", "Which statement about electric field lines is correct?", "Their density indicates field strength, and no two field lines cross",
      ["They are the paths followed by charged particles in an electric field", "They start at negative charges and end at positive charges", "They are real curves that physically exist"],
      "Field lines are imaginary curves for visualizing an electric field; they are neither physical objects nor particle trajectories. They start at positive charges and end at negative charges. Since a point has only one field direction, field lines cannot cross."),
    N("basic", "At a point P, charges A and B produce fields of 3 N/C and 4 N/C in perpendicular directions. What is the magnitude of the net field at P, in N/C? (Enter a number only)", "5",
      "Electric field is a vector, so combine the two fields using the parallelogram rule: E = √(3² + 4²) = 5 N/C. Directly adding to get 7 N/C ignores direction.", "sqrt(3**2+4**2)"),
    N("standard", "Two equal and opposite point charges in a vacuum are +2×10⁻⁹ C and −2×10⁻⁹ C. Their midpoint is 0.3 m from each charge. What is the net field strength there, in N/C? (k = 9×10⁹ N·m²/C²; enter a number only)", "400",
      "Each charge produces E₁ = kQ/r² = 9×10⁹ × 2×10⁻⁹ ÷ 0.09 = 200 N/C at the midpoint. Both fields point from the positive charge toward the negative one, so they add to 400 N/C. For equal like charges, the fields point in opposite directions and cancel.", "round(2*9e9*2e-9/0.3**2)"),
    C("standard", "A negatively charged particle is released from rest in a uniform electric field and is acted on only by the electric force. In which direction does it move?", "Opposite to the electric field lines",
      ["Along the electric field lines", "Perpendicular to the electric field lines", "First along the field lines, then opposite to them"],
      "The force on a negative charge is opposite the field direction, which is the tangent direction of the field lines. Released from rest, it accelerates along the force, opposite to the field lines."),
  ])

T("electrostatic_app", "Prevention and Applications of Static Electricity", "Motion and Interaction", "application",
  "In electrostatic equilibrium, the electric field inside a conductor is zero everywhere, and net charge lies only on its outer surface; this gives rise to electrostatic shielding. The field is very strong near a sharp point, causing corona discharge. Lightning rods, electrostatic precipitators, and electrostatic painting use static electricity; grounding chains on tanker trucks help prevent static hazards.",
  ["State the properties of a conductor in electrostatic equilibrium", "Explain electrostatic shielding and corona discharge", "Distinguish applications of static electricity from measures that prevent its hazards"],
  [("B3.1.4", "exact"), ("B3.1.1", "inferred")],
  pre=[("field_lines", "hard"), ("charge", "hard")],
  qs=[
    C("basic", "Workers performing live high-voltage work wear a conductive suit woven from metal threads. Which principle does this mainly use?", "Electrostatic shielding",
      ["Corona discharge", "Electromagnetic induction", "Electrostatic attraction"],
      "The woven suit acts like a metal mesh cage, providing electrostatic shielding that makes the field inside zero and protects the wearer from the high-voltage field."),
    C("basic", "Why does a lightning rod help protect a building from lightning?", "Corona discharge at its tip continually drains charge from the cloud to the ground",
      ["It reflects lightning back toward the cloud", "Its metal rod shields the building so lightning cannot approach", "It carries a positive charge that absorbs and stores lightning"],
      "The strong field near the rod's tip causes continuous discharge into the air, neutralizing charge in the cloud. A wire then carries charge to the ground, helping protect the building."),
    C("standard", "Which statement about a conductor in electrostatic equilibrium is correct?", "The net field inside is zero everywhere, and net charge lies only on the conductor's surface",
      ["Charges inside the conductor move directionally, forming a steady current", "Net charge is distributed uniformly throughout the conductor", "The induced field points in the same direction as the external field inside, doubling the field strength"],
      "In electrostatic equilibrium, free charges no longer move directionally. Inside the conductor, the induced field equals the external field in magnitude and points in the opposite direction, making the net field zero. Net charge lies on the outer surface."),
    C("standard", "Which practice helps prevent a static-electricity hazard?", "A tanker truck drags a grounded metal chain behind it",
      ["Using an electrostatic precipitator to remove particles from exhaust", "Using electrostatic painting on a car body", "Using static electricity to attract toner in a laser printer"],
      "As a tanker truck moves, friction between the fuel and tank wall can build up charge. The chain grounds it to prevent sparks from igniting fuel; the other choices are applications of static electricity."),
  ])
